private void xrTableCell116_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
 double vjetersi =  Convert.ToInt32(GetCurrentColumnValue("vjetersia"));
if(vjetersi  ==0)
                xrTableCell116.Text = "0";
            else
            {
              xrTableCell116.Text = String.Format("{0:#,#}", vjetersi);
              xrTableCell116.XlsxFormatString = "#,##0";

            }

}

